CREATE TYPE public.app_role AS ENUM ('admin', 'content_manager', 'support');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.site_content (key text PRIMARY KEY, title text NOT NULL, body text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'page', published boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_content TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_content TO authenticated;
GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_content ON public.site_content FOR SELECT TO anon USING (published);
CREATE POLICY staff_content ON public.site_content FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'content_manager')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'content_manager'));
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 100), email text NOT NULL CHECK (char_length(email) <= 255), phone text NOT NULL DEFAULT '', company text NOT NULL DEFAULT '', product text NOT NULL DEFAULT '', message text NOT NULL CHECK (char_length(message) BETWEEN 3 AND 5000), kind text NOT NULL DEFAULT 'contact' CHECK(kind IN ('contact','quote','distributor')), location text NOT NULL DEFAULT '', preferred_contact text NOT NULL DEFAULT 'email', status text NOT NULL DEFAULT 'New', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.enquiries TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.enquiries TO authenticated;
GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_enquiry_insert ON public.enquiries FOR INSERT TO anon WITH CHECK (status = 'New' AND notes = '');
CREATE POLICY staff_enquiries ON public.enquiries FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'support')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'support'));
CREATE TABLE public.visitor_chats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, messages jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.visitor_chats TO authenticated;
GRANT ALL ON public.visitor_chats TO service_role;
ALTER TABLE public.visitor_chats ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_chats ON public.visitor_chats FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'support'));
CREATE TABLE public.ai_access_state (id text PRIMARY KEY, blocked boolean NOT NULL DEFAULT false, reason text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_access_state TO service_role;
ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.request_limits (key text PRIMARY KEY, count integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.request_limits TO service_role;
ALTER TABLE public.request_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.check_request_limit(_key text, _limit integer, _seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE c integer; BEGIN INSERT INTO public.request_limits(key) VALUES(_key) ON CONFLICT(key) DO UPDATE SET count = CASE WHEN request_limits.window_start < now() - make_interval(secs => _seconds) THEN 1 ELSE request_limits.count + 1 END, window_start = CASE WHEN request_limits.window_start < now() - make_interval(secs => _seconds) THEN now() ELSE request_limits.window_start END RETURNING count INTO c; RETURN c <= _limit; END $$;
REVOKE ALL ON FUNCTION public.check_request_limit(text,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.check_request_limit(text,integer,integer) TO service_role;
CREATE INDEX enquiries_created ON public.enquiries(created_at DESC);